j:jelly.g:evaluate:
// Calls come from the database, never from a URL parameter, so this page can only ever frame the
// Dynamics 365 environment configured in d365cc.org_url.
var util = new D365CCUtil();
var list = [];
var callId = String(RP.getParameterValue('sysparm_call') || '');
var caseId = String(RP.getParameterValue('sysparm_case') || '');
var gr = new GlideRecord('u_cc_call');
if (callId) gr.addQuery('sys_id', callId);
else if (caseId) gr.addQuery('u_case', caseId);
else gr.addQuery('sys_id', 'none');
gr.orderByDesc('u_call_received');
gr.setLimit(25);
gr.query();
while (gr.next()) {
    var url = util.conversationUrl(gr.getValue('u_conversation_id'), true);
    if (!url) continue;
    list.push({ id: gr.getUniqueValue(), title: gr.getValue('u_title') || 'Call', agent: gr.getValue('u_agent') || '', url: url, open: util.conversationUrl(gr.getValue('u_conversation_id'), false) });
}
JSON.stringify(list);

j:jelly.script:
var calls = JSON.parse(document.getElementById('calls-data').getAttribute('data-calls') || '[]');
function show(i) {
    var c = calls[i];
    document.getElementById('d365-loading').style.display = 'flex';
    document.getElementById('d365-frame').src = c.url;
    document.getElementById('newtab').href = c.open;
    var t = document.querySelectorAll('.tab');
    for (var k = 0; k !== t.length; k++) t[k].className = 'tab' + (k === i ? ' on' : '');
}
if (calls.length === 0) {
    document.getElementById('wrap').style.display = 'none';
    document.getElementById('footer').style.display = 'none';
    document.getElementById('empty').style.display = 'block';
} else {
    if (calls.length !== 1) {
        var bar = document.getElementById('tabs');
        bar.style.display = 'flex';
        document.getElementById('wrap').style.top = '44px';
        for (var n = 0; n !== calls.length; n++) {
            var b = document.createElement('div');
            b.className = 'tab';
            b.textContent = calls[n].title.replace('Phone call received on ', '') + (calls[n].agent ? ' · ' + calls[n].agent : '');
            b.setAttribute('data-i', n);
            b.onclick = function () { show(parseInt(this.getAttribute('data-i'), 10)); };
            bar.appendChild(b);
        }
    }
    show(0);
}
// Workspace caps its modal at 800x600 (.now-modal-dialog). This page is same-origin with the Workspace, so it
// lifts that cap and fills the window; harmless when the page is opened outside a Workspace modal.
function growModal() {
    try {
        var top = window.parent, h = Math.floor(top.innerHeight * 0.94), w = Math.floor(top.innerWidth * 0.96);
        var n = window.frameElement, dialog = null, body = null;
        while (n) {
            var c = n.classList;
            if (c) { if (c.contains('now-modal-dialog')) dialog = n; if (c.contains('now-modal-body')) body = n; }
            n = n.assignedSlot || (n.parentNode ? n.parentNode.host : null) || n.parentElement;
        }
        if (!dialog) return;
        if (!body) return;
        var set = function (el, k, v) { el.style.setProperty(k, v, 'important'); };
        set(dialog, 'max-width', w + 'px'); set(dialog, 'width', w + 'px');
        set(dialog, 'max-height', h + 'px'); set(dialog, 'height', h + 'px');
        var head = h - 90;
        set(body, 'max-height', head + 'px'); set(body, 'height', head + 'px');
        var fe = window.frameElement;
        set(fe, 'width', '100%'); set(fe, 'height', head - 20 + 'px');
        if (fe.parentElement) { set(fe.parentElement, 'width', '100%'); set(fe.parentElement, 'height', head - 20 + 'px'); }
    } catch (e) { }
}
growModal();
setTimeout(growModal, 300);
setTimeout(growModal, 1200);
